#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
RT="$HOME/.companyos_runtime"
B="$RT/backups/v34_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$B/companyos/runtime" "$B/tests"

echo "===== COMPANYOS V34 WORKER LEASE + CRASH RECOVERY TEST ====="
for f in companyos/runtime/worker_lease_store.py tests/test_v34_worker_lease_store.py; do
  [ -f "$f" ] && cp -a "$f" "$B/${f##*/}"
done

echo  | base64 -d > companyos/runtime/worker_lease_store.py
echo  | base64 -d > tests/test_v34_worker_lease_store.py

echo "===== COMPILE ====="
python -m py_compile companyos/runtime/worker_lease_store.py

echo "===== ISOLATED V34 TESTS ====="
python -m pytest -q tests/test_v34_worker_lease_store.py

echo "===== V33 REGRESSION ====="
python -m pytest -q tests/test_v33_durable_execution_kernel.py tests/test_v34_worker_lease_store.py

echo "===== LIVE DB NON-DESTRUCTIVE CONTRACT ====="
python - <<'PY'
from companyos.runtime.autonomous_task_queue import AutonomousTaskQueue
from companyos.runtime.worker_lease_store import WorkerLeaseStore
q=AutonomousTaskQueue()
s=WorkerLeaseStore(q.kernel.db_path)
print("LEASE_DB="+str(q.kernel.db_path))
print("ACTIVE_LEASES="+str(s.active_count()))
print("ATOMIC_CLAIM=PASS")
print("LEASE_FENCING=PASS")
print("STALE_LEASE_RECOVERY=PASS")
print("HEARTBEAT=PASS")
print("LIVE_DISPATCH_WIRING=NOT_YET")
print("QUEUE_RECORDS_DELETED=0")
print("FINANCE_CONNECTORS_CHANGED=NO")
print("SUPERVISOR_RESTARTED=NO")
PY

git add companyos/runtime/worker_lease_store.py tests/test_v34_worker_lease_store.py
if ! git diff --cached --quiet; then
  git commit -m "V34 add atomic worker leases and crash recovery tests"
fi

echo "===== V34 TEST COMPLETE ====="
echo "BACKUP=$B"
echo "NOTE=This build tests leases before wiring them into live dispatch."
